INSERT INTO results (id, tag, type, title, statement_tex, statement_html_cache, section_id, position, visibility, listed, revision, created_at, updated_at, created_by, updated_by) VALUES (141, '8JTA', 'example', 'The Riemann zeta function', 'Take $\psi = \mathbf 1$, the \hyperref[8JH4]{trivial character}, so that $L(s, \mathbf 1) = \zeta(s)$ and $o = 1$. The \hyperref[8JG8]{cyclic family} is $\mathcal C_{\mathbf 1} = \{\mathbf 1\}$ with weight $a_{\mathbf 1} = 1$, so the weighted sum is the \hyperref[8JF7]{smoothed prime sum} of the \hyperref[8JS9]{trivial character}:
\[ \mathcal G_{\mathbf 1}(x) = G_{\mathbf 1}(x) = \sum_{n \le x} \Lambda(n)\Bigl(\frac xn - 1\Bigr) - x\log x + (1+\gamma)x. \]

\emph{Poles.} By \ref{8JS6} and \ref{8JN4}, the Mellin transform
\[ H_{\mathbf 1}(s) = -\frac{\zeta''}{\zeta}(s)\,\frac{1}{s(s-1)} - \frac{1}{(s-1)^2} + \frac{1+\gamma}{s-1} \]
has a simple pole at each nontrivial zero $\rho$ of $\zeta$, with residue $-m(\rho)/(\rho(\rho-1))$, where $m(\rho)$ is the multiplicity. None of these poles is real, because $\zeta(s) < 0$ for $0 < s < 1$: there $(1 - 2^{1-s})\zeta(s) = 1 - 2^{-s} + 3^{-s} - \cdots > 0$ and $1 - 2^{1-s} < 0$. So for $\zeta$ only case (a) in the proof of the \hyperref[8JT5]{lower bound} can occur.

\emph{Explicit formula.} Since $\frac{1}{2\pi i}\int_{(2)} \frac{y^s}{s(s-1)}\,ds = (y - 1)_+$ for $y > 0$, we have
\[ \sum_{n \le x} \Lambda(n)\Bigl(\frac xn - 1\Bigr) = \frac{1}{2\pi i}\int_{2 - i\infty}^{2 + i\infty} -\frac{\zeta''}{\zeta}(s)\,\frac{x^s}{s(s-1)}\,ds. \]
Moving the line of integration to the left and collecting residues gives, for $x \ge 1$,
\[ G_{\mathbf 1}(x) = \log 2\pi - \sum_\rho \frac{x^\rho}{\rho(\rho - 1)} - \sum_{n \ge 1} \frac{x^{-2n}}{2n(2n+1)}, \]
where $\rho$ runs over the nontrivial zeros with multiplicity and the sum converges absolutely \cite{Davenport}. The residue at $s = 1$ is the main term $x\log x - (1+\gamma)x$, which $G_{\mathbf 1}$ subtracts; the three terms that remain come from $s = 0$ (where $\frac{\zeta''}{\zeta}(0) = \log 2\pi$), from the zeros $\rho$, and from the trivial zeros $-2n$. So each zero $\rho = \beta + i\gamma$ adds an oscillation $x^\rho = x^\beta e^{i\gamma\log x}$ of size $x^\beta$.

\emph{Taylor coefficients.} Since $\int_1^\infty x^\rho\, x^{-s-1}\,dx = \frac{1}{s - \rho}$ for $\Re s > \Re\rho$, the \hyperref[8JS2]{Mellin transform} of the explicit formula is
\begin{align*}
H_{\mathbf 1}(s) = \frac{\log 2\pi}{s} &- \sum_\rho \frac{1}{\rho(\rho-1)(s - \rho)} \\
&- \sum_{n \ge 1} \frac{1}{2n(2n+1)(s + 2n)}.
\end{align*}
Hence, for $\Re z > 1$ and $k \ge 0$, the coefficients $A_k(z) = \frac{(-1)^k}{k!}H_{\mathbf 1}^{(k)}(z)$ of the \hyperref[8JT2]{one-sided bound} are
\begin{align*}
A_k(z) = \frac{\log 2\pi}{z^{k+1}} &- \sum_\rho \frac{1}{\rho(\rho-1)(z - \rho)^{k+1}} \\
&- \sum_{n \ge 1} \frac{1}{2n(2n+1)(z + 2n)^{k+1}}.
\end{align*}
Each pole $p$ of $H_{\mathbf 1}$, with residue $c$, contributes $c/(z - p)^{k+1}$, so for large $k$ the poles nearest to $z$ dominate. This is the mechanism behind the \hyperref[8JT2]{one-sided bound} and the \hyperref[8JT5]{lower bound}.

\emph{What the theorem says here.} For $\psi = \mathbf 1$ the \hyperref[8JK2]{interval estimate} only asks that $G_{\mathbf 1}(x) \le x^{1/2 + 9\varepsilon}$ on sparse intervals $[Y, Y^{3/2}]$, and \ref{8JR6} turns this into the Riemann hypothesis. Conversely, if the Riemann hypothesis holds, then $|x^\rho| = \sqrt x$ and $\rho(1 - \rho) = |\rho|^2$ for every zero, and $\sum_\rho \frac{1}{\rho(1-\rho)} = 2 + \gamma - \log 4\pi \approx 0.0462$ \cite{Davenport}. With $\sum_{n \ge 1} \frac{1}{2n(2n+1)} = 1 - \log 2 < 0.307$, the explicit formula then gives the much stronger two-sided bound
\[ |G_{\mathbf 1}(x) - \log 2\pi| \le 0.0462\sqrt x + 0.307 \qquad (x \ge 1). \]

\emph{Graphs.} Panel (a) shows $G_{\mathbf 1}(x)$ for $1 \le x \le 10^7$, on a logarithmic $x$-axis, with this bound dashed.
\includegraphics[width=1, alt=G_1(x) for x from 1 to 10 million on a logarithmic axis, oscillating with amplitude up to about 45, well inside the dashed curves log 2 pi plus or minus (0.0462 sqrt x + 0.307)]{/static/figures/zeta-smoothed-sum.svg}
Panel (b) shows $(G_{\mathbf 1}(x) - \log 2\pi)/\sqrt x$ for $10 \le x \le 10^7$, together with the explicit formula cut off after the first zero pair $\frac12 \pm 14.1347\,i$, which is a pure wave in $\log x$, and after the first ten zero pairs, which already follows the data closely.
\includegraphics[width=1, alt=The normalized smoothed sum oscillating with size about 0.01 to 0.02, the first zero pair giving a pure wave and the first ten zero pairs following the data closely]{/static/figures/zeta-oscillation.svg}
Panel (c) shows $|A_k(\frac32 + i\tau)|$ for $k = 0, 1, 2, 3$ and $0 \le \tau \le 50$, on a logarithmic scale; the dotted lines mark the heights $\gamma$ of the zeros $\frac12 + i\gamma$. Here $\sigma - \frac12 = 1$, so at $\tau = \gamma$ the zero $\rho = \frac12 + i\gamma$ contributes a term of size $1/|\rho|^2$ for every $k$, while the terms of the farther poles shrink as $k$ grows. For $k = 0$ and $1$ the pole at $s = 0$, with its comparatively large residue $\log 2\pi \approx 1.84$, still dominates, and the zeros only make small dents. From $k = 2$ on, peaks of height about $1/|\rho|^2$ appear at the zeros. A zero $\beta + i\gamma$ with $\beta > \frac12$ would instead give peaks growing like $(\frac32 - \beta)^{-k}$, which is what the \hyperref[8JT5]{lower bound} detects.
\includegraphics[width=1, alt=The absolute values of A_0 to A_3 on the line Re s = 3/2 for tau from 0 to 50 on a logarithmic scale, with peaks at the heights of the zeros of zeta appearing from k = 2 on]{/static/figures/zeta-taylor-coefficients.svg}', NULL, 104, 11, 'published', 1, 1, '2026-11-25 02:30:00', '2026-11-25 02:30:00', 'claude', 'claude');
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '141', 1, 'zeta-example-2026-11-25', '{"tag":"8JTA","type":"example","title":"The Riemann zeta function","statement_tex":"Take $\\psi = \\mathbf 1$, the \\hyperref[8JH4]{trivial character}, so that $L(s, \\mathbf 1) = \\zeta(s)$ and $o = 1$. The \\hyperref[8JG8]{cyclic family} is $\\mathcal C_{\\mathbf 1} = \\{\\mathbf 1\\}$ with weight $a_{\\mathbf 1} = 1$, so the weighted sum is the \\hyperref[8JF7]{smoothed prime sum} of the \\hyperref[8JS9]{trivial character}:\n\\[ \\mathcal G_{\\mathbf 1}(x) = G_{\\mathbf 1}(x) = \\sum_{n \\le x} \\Lambda(n)\\Bigl(\\frac xn - 1\\Bigr) - x\\log x + (1+\\gamma)x. \\]\n\n\\emph{Poles.} By \\ref{8JS6} and \\ref{8JN4}, the Mellin transform\n\\[ H_{\\mathbf 1}(s) = -\\frac{\\zeta''}{\\zeta}(s)\\,\\frac{1}{s(s-1)} - \\frac{1}{(s-1)^2} + \\frac{1+\\gamma}{s-1} \\]\nhas a simple pole at each nontrivial zero $\\rho$ of $\\zeta$, with residue $-m(\\rho)/(\\rho(\\rho-1))$, where $m(\\rho)$ is the multiplicity. None of these poles is real, because $\\zeta(s) < 0$ for $0 < s < 1$: there $(1 - 2^{1-s})\\zeta(s) = 1 - 2^{-s} + 3^{-s} - \\cdots > 0$ and $1 - 2^{1-s} < 0$. So for $\\zeta$ only case (a) in the proof of the \\hyperref[8JT5]{lower bound} can occur.\n\n\\emph{Explicit formula.} Since $\\frac{1}{2\\pi i}\\int_{(2)} \\frac{y^s}{s(s-1)}\\,ds = (y - 1)_+$ for $y > 0$, we have\n\\[ \\sum_{n \\le x} \\Lambda(n)\\Bigl(\\frac xn - 1\\Bigr) = \\frac{1}{2\\pi i}\\int_{2 - i\\infty}^{2 + i\\infty} -\\frac{\\zeta''}{\\zeta}(s)\\,\\frac{x^s}{s(s-1)}\\,ds. \\]\nMoving the line of integration to the left and collecting residues gives, for $x \\ge 1$,\n\\[ G_{\\mathbf 1}(x) = \\log 2\\pi - \\sum_\\rho \\frac{x^\\rho}{\\rho(\\rho - 1)} - \\sum_{n \\ge 1} \\frac{x^{-2n}}{2n(2n+1)}, \\]\nwhere $\\rho$ runs over the nontrivial zeros with multiplicity and the sum converges absolutely \\cite{Davenport}. The residue at $s = 1$ is the main term $x\\log x - (1+\\gamma)x$, which $G_{\\mathbf 1}$ subtracts; the three terms that remain come from $s = 0$ (where $\\frac{\\zeta''}{\\zeta}(0) = \\log 2\\pi$), from the zeros $\\rho$, and from the trivial zeros $-2n$. So each zero $\\rho = \\beta + i\\gamma$ adds an oscillation $x^\\rho = x^\\beta e^{i\\gamma\\log x}$ of size $x^\\beta$.\n\n\\emph{Taylor coefficients.} Since $\\int_1^\\infty x^\\rho\\, x^{-s-1}\\,dx = \\frac{1}{s - \\rho}$ for $\\Re s > \\Re\\rho$, the \\hyperref[8JS2]{Mellin transform} of the explicit formula is\n\\begin{align*}\nH_{\\mathbf 1}(s) = \\frac{\\log 2\\pi}{s} &- \\sum_\\rho \\frac{1}{\\rho(\\rho-1)(s - \\rho)} \\\\\n&- \\sum_{n \\ge 1} \\frac{1}{2n(2n+1)(s + 2n)}.\n\\end{align*}\nHence, for $\\Re z > 1$ and $k \\ge 0$, the coefficients $A_k(z) = \\frac{(-1)^k}{k!}H_{\\mathbf 1}^{(k)}(z)$ of the \\hyperref[8JT2]{one-sided bound} are\n\\begin{align*}\nA_k(z) = \\frac{\\log 2\\pi}{z^{k+1}} &- \\sum_\\rho \\frac{1}{\\rho(\\rho-1)(z - \\rho)^{k+1}} \\\\\n&- \\sum_{n \\ge 1} \\frac{1}{2n(2n+1)(z + 2n)^{k+1}}.\n\\end{align*}\nEach pole $p$ of $H_{\\mathbf 1}$, with residue $c$, contributes $c/(z - p)^{k+1}$, so for large $k$ the poles nearest to $z$ dominate. This is the mechanism behind the \\hyperref[8JT2]{one-sided bound} and the \\hyperref[8JT5]{lower bound}.\n\n\\emph{What the theorem says here.} For $\\psi = \\mathbf 1$ the \\hyperref[8JK2]{interval estimate} only asks that $G_{\\mathbf 1}(x) \\le x^{1/2 + 9\\varepsilon}$ on sparse intervals $[Y, Y^{3/2}]$, and \\ref{8JR6} turns this into the Riemann hypothesis. Conversely, if the Riemann hypothesis holds, then $|x^\\rho| = \\sqrt x$ and $\\rho(1 - \\rho) = |\\rho|^2$ for every zero, and $\\sum_\\rho \\frac{1}{\\rho(1-\\rho)} = 2 + \\gamma - \\log 4\\pi \\approx 0.0462$ \\cite{Davenport}. With $\\sum_{n \\ge 1} \\frac{1}{2n(2n+1)} = 1 - \\log 2 < 0.307$, the explicit formula then gives the much stronger two-sided bound\n\\[ |G_{\\mathbf 1}(x) - \\log 2\\pi| \\le 0.0462\\sqrt x + 0.307 \\qquad (x \\ge 1). \\]\n\n\\emph{Graphs.} Panel (a) shows $G_{\\mathbf 1}(x)$ for $1 \\le x \\le 10^7$, on a logarithmic $x$-axis, with this bound dashed.\n\\includegraphics[width=1, alt=G_1(x) for x from 1 to 10 million on a logarithmic axis, oscillating with amplitude up to about 45, well inside the dashed curves log 2 pi plus or minus (0.0462 sqrt x + 0.307)]{/static/figures/zeta-smoothed-sum.svg}\nPanel (b) shows $(G_{\\mathbf 1}(x) - \\log 2\\pi)/\\sqrt x$ for $10 \\le x \\le 10^7$, together with the explicit formula cut off after the first zero pair $\\frac12 \\pm 14.1347\\,i$, which is a pure wave in $\\log x$, and after the first ten zero pairs, which already follows the data closely.\n\\includegraphics[width=1, alt=The normalized smoothed sum oscillating with size about 0.01 to 0.02, the first zero pair giving a pure wave and the first ten zero pairs following the data closely]{/static/figures/zeta-oscillation.svg}\nPanel (c) shows $|A_k(\\frac32 + i\\tau)|$ for $k = 0, 1, 2, 3$ and $0 \\le \\tau \\le 50$, on a logarithmic scale; the dotted lines mark the heights $\\gamma$ of the zeros $\\frac12 + i\\gamma$. Here $\\sigma - \\frac12 = 1$, so at $\\tau = \\gamma$ the zero $\\rho = \\frac12 + i\\gamma$ contributes a term of size $1/|\\rho|^2$ for every $k$, while the terms of the farther poles shrink as $k$ grows. For $k = 0$ and $1$ the pole at $s = 0$, with its comparatively large residue $\\log 2\\pi \\approx 1.84$, still dominates, and the zeros only make small dents. From $k = 2$ on, peaks of height about $1/|\\rho|^2$ appear at the zeros. A zero $\\beta + i\\gamma$ with $\\beta > \\frac12$ would instead give peaks growing like $(\\frac32 - \\beta)^{-k}$, which is what the \\hyperref[8JT5]{lower bound} detects.\n\\includegraphics[width=1, alt=The absolute values of A_0 to A_3 on the line Re s = 3/2 for tau from 0 to 50 on a logarithmic scale, with peaks at the heights of the zeros of zeta appearing from k = 2 on]{/static/figures/zeta-taylor-coefficients.svg}"